#!/usr/bin/env python3
"""Test tool calling support on candidate models."""
import asyncio
import json
import sys
import os
from pathlib import Path

sys.path.insert(0, "/home/ubuntu/agent-ml-research")
from core.crypto import load_secret
key = load_secret(Path(
    "/home/ubuntu/.agent-ml-research-be-idea-gen-0519-4"
    "/config/secrets/policy_ambiguity_safety/openrouter_api_key.enc"
))
os.environ["OPENROUTER_API_KEY"] = key

import openai

candidates = [
    "google/gemini-2.5-flash",
    "google/gemini-2.5-pro",
    "meta-llama/llama-4-maverick",
    "meta-llama/llama-4-scout",
]

tools = [
    {
        "type": "function",
        "function": {
            "name": "get_order_details",
            "description": "Get details of a specific order.",
            "parameters": {
                "type": "object",
                "properties": {
                    "order_id": {"type": "string", "description": "The order ID"}
                },
                "required": ["order_id"]
            }
        }
    }
]

system_prompt = """You are a customer service agent. Follow the policy below.
<policy>
Customers may return items within 30 days of purchase. Check order details before processing any return.
</policy>"""

user_msg = "Hi, I'd like to return my order #12345."

client = openai.AsyncOpenAI(base_url="http://47.94.22.126/v1", api_key=[REDACTED]

async def test_one(model_id: str) -> tuple[str, str]:
    try:
        response = await client.chat.completions.create(
            model=model_id,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_msg},
            ],
            tools=tools,
            max_tokens=256,
            timeout=60,
        )
        choice = response.choices[0]
        msg = choice.message
        text = msg.content or ""
        tc = []
        if msg.tool_calls:
            for t in msg.tool_calls:
                tc.append(f"{t.function.name}({t.function.arguments})")
        if tc:
            return (model_id, f"TOOL_CALL: {'; '.join(tc)}")
        return (model_id, f"TEXT: {text[:100]}")
    except Exception as e:
        return (model_id, f"ERROR: {str(e)[:150]}")

async def main():
    results = await asyncio.gather(*[test_one(m) for m in candidates])
    for model_id, result in results:
        print(f"\n{model_id}:")
        print(f"  {result}")

asyncio.run(main())

